-- 费用更正新增结构由 Ent Schema diff 生成；只选取本任务新列、来源外键、CHECK 与索引，保留现有结构。
ALTER TABLE "finance_bills" ADD COLUMN "purpose" character varying NOT NULL DEFAULT 'NORMAL';
ALTER TABLE "finance_commission_adjustments" ADD CONSTRAINT "commission_adjustment_source_correction_check" CHECK ((source_type = 'FEE_CORRECTION' AND source_fee_correction_request_id IS NOT NULL) OR (source_type <> 'FEE_CORRECTION' AND source_fee_correction_request_id IS NULL)), ADD CONSTRAINT "commission_adjustment_source_reallocation_check" CHECK (source_type <> 'ECONOMIC_REALLOCATION' OR ((source_verification_id IS NOT NULL AND source_netting_id IS NULL) OR (source_verification_id IS NULL AND source_netting_id IS NOT NULL))), ADD COLUMN "source_netting_id" uuid NULL, ADD COLUMN "source_fee_correction_request_id" uuid NULL, ADD COLUMN "superseded_by_fee_correction_request_id" uuid NULL;
DROP INDEX "financecommissionadjustment_reversal_source";
-- 开发库中已确认存在 Ent 生成的同列无条件唯一索引；正式迁移冷启动没有该索引。
-- 两个旧索引必须一并移除，否则同名重建失败，或旧约束继续阻止经济重分配。
DROP INDEX IF EXISTS "financecommissionadjustment_co_36fb58015f1b066e73dc271e344c49a4";
CREATE UNIQUE INDEX "financecommissionadjustment_co_36fb58015f1b066e73dc271e344c49a4" ON "finance_commission_adjustments" ("commission_id", "order_id", "source_type", "source_verification_id") WHERE source_type <> 'ECONOMIC_REALLOCATION';
CREATE UNIQUE INDEX "financecommissionadjustment_co_a23fb6e30d6c19c42833706d375fe141" ON "finance_commission_adjustments" ("commission_id", "order_id", "source_fee_correction_request_id");
ALTER TABLE "finance_commission_lines" ADD COLUMN "fee_content_version_snapshot" bigint NOT NULL DEFAULT 1, ADD COLUMN "realization_snapshot" jsonb NOT NULL DEFAULT '{}';
ALTER TABLE "finance_netting_allocations" ADD COLUMN "source_fee_id" uuid NULL;
ALTER TABLE "finance_nettings" ADD COLUMN "correction_request_id" uuid NULL;
ALTER TABLE "order_fee_review_events" ADD COLUMN "correction_request_id" uuid NULL;
ALTER TABLE "order_fees" ADD CONSTRAINT "order_fee_economic_effect_check" CHECK (economic_effect IN ('INCREASE','DECREASE') AND (source_fee_id IS NULL OR (correction_request_id IS NOT NULL AND source_fee_id <> id)) AND (economic_effect = 'INCREASE' OR (source_fee_id IS NOT NULL AND correction_request_id IS NOT NULL AND superseded_by_request_id IS NULL))), ADD COLUMN "economic_effect" character varying NOT NULL DEFAULT 'INCREASE', ADD COLUMN "accounting_required" boolean NOT NULL DEFAULT true, ADD COLUMN "source_fee_id" uuid NULL, ADD COLUMN "correction_request_id" uuid NULL, ADD COLUMN "superseded_by_request_id" uuid NULL;
CREATE UNIQUE INDEX "orderfee_correction_request_id_economic_effect" ON "order_fees" ("correction_request_id", "economic_effect");
CREATE UNIQUE INDEX "orderfee_source_fee_id_economic_effect" ON "order_fees" ("source_fee_id", "economic_effect") WHERE economic_effect = 'DECREASE';
CREATE TABLE "order_fee_correction_requests" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "operation" character varying NOT NULL, "source_fee_version" bigint NULL, "before_snapshot" jsonb NULL, "after_snapshot" jsonb NULL, "approved_fee_review_event_id" uuid NOT NULL, "approved_fee_content_version" bigint NOT NULL, "approved_fee_review_version" bigint NOT NULL, "approval_result_snapshot" jsonb NULL, "reason" character varying NOT NULL, "idempotency_key" character varying NOT NULL, "request_fingerprint" character varying NOT NULL, "requested_at" timestamptz NOT NULL, "status" character varying NOT NULL DEFAULT 'PENDING', "version" bigint NOT NULL DEFAULT 1, "decided_at" timestamptz NULL, "decision_reason" character varying NULL, "approval_token" character varying NULL, "order_id" uuid NOT NULL, "source_fee_id" uuid NULL, "organization_id" uuid NOT NULL, "requested_by" uuid NOT NULL, "decided_by" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "order_fee_correction_approval_basis_check" CHECK (approved_fee_content_version > 0 AND version > 0), CONSTRAINT "order_fee_correction_operation_check" CHECK ((operation = 'ADD' AND source_fee_id IS NULL AND before_snapshot IS NULL AND after_snapshot IS NOT NULL) OR (operation = 'REPLACE' AND source_fee_id IS NOT NULL AND before_snapshot IS NOT NULL AND after_snapshot IS NOT NULL) OR (operation = 'VOID' AND source_fee_id IS NOT NULL AND before_snapshot IS NOT NULL AND after_snapshot IS NULL)), CONSTRAINT "order_fee_correction_status_check" CHECK (status IN ('PENDING','APPROVED','REJECTED','WITHDRAWN')));
CREATE INDEX "orderfeecorrectionrequest_updated_at" ON "order_fee_correction_requests" ("updated_at");
CREATE UNIQUE INDEX "orderfeecorrectionrequest_organization_id_idempotency_key" ON "order_fee_correction_requests" ("organization_id", "idempotency_key");
CREATE INDEX "orderfeecorrectionrequest_organization_id_order_id_requested_at" ON "order_fee_correction_requests" ("organization_id", "order_id", "requested_at");
CREATE UNIQUE INDEX "order_fee_correction_one_pending" ON "order_fee_correction_requests" ("order_id") WHERE status = 'PENDING';
ALTER TABLE "finance_commission_adjustments" ADD CONSTRAINT "finance_commission_adjustments_3b8c2be748427ab5e5855e1fbf5a0ce3" FOREIGN KEY ("source_netting_id") REFERENCES "finance_nettings" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "finance_commission_adjustments_33614fab2b77cad4a4edc1b144875bd3" FOREIGN KEY ("source_fee_correction_request_id") REFERENCES "order_fee_correction_requests" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "finance_commission_adjustments_ec496be7c3fa0401d2ca919e8dba882d" FOREIGN KEY ("superseded_by_fee_correction_request_id") REFERENCES "order_fee_correction_requests" ("id") ON DELETE NO ACTION;
ALTER TABLE "finance_netting_allocations" ADD CONSTRAINT "finance_netting_allocations_or_74bb805b69771f1786b53449dddd9cc3" FOREIGN KEY ("source_fee_id") REFERENCES "order_fees" ("id") ON DELETE NO ACTION;
ALTER TABLE "finance_nettings" ADD CONSTRAINT "finance_nettings_order_fee_correction_requests_nettings" FOREIGN KEY ("correction_request_id") REFERENCES "order_fee_correction_requests" ("id") ON DELETE NO ACTION;
ALTER TABLE "order_fees" ADD CONSTRAINT "order_fees_order_fees_derived_fees" FOREIGN KEY ("source_fee_id") REFERENCES "order_fees" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "order_fees_order_fee_correction_requests_generated_fees" FOREIGN KEY ("correction_request_id") REFERENCES "order_fee_correction_requests" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "order_fees_order_fee_correction_requests_superseded_fees" FOREIGN KEY ("superseded_by_request_id") REFERENCES "order_fee_correction_requests" ("id") ON DELETE NO ACTION;
ALTER TABLE "order_fee_correction_requests" ADD CONSTRAINT "order_fee_correction_requests_orders_fee_correction_requests" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "order_fee_correction_requests__2150d836c34b62e4f3cf2cefe534ff08" FOREIGN KEY ("source_fee_id") REFERENCES "order_fees" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "order_fee_correction_requests__ad9f3c283758e77c22f9f0e29653dfe2" FOREIGN KEY ("organization_id") REFERENCES "organizations" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "order_fee_correction_requests__2b5dd744ce986509fe4748043bffb17f" FOREIGN KEY ("requested_by") REFERENCES "users" ("id") ON DELETE NO ACTION, ADD CONSTRAINT "order_fee_correction_requests__2c5befb06fc0d9f17717035a25ac283c" FOREIGN KEY ("decided_by") REFERENCES "users" ("id") ON DELETE SET NULL;

-- 同名枚举 CHECK 的扩展需显式置换，表达式与源 Schema 注解保持一致。
ALTER TABLE "finance_commission_adjustments" DROP CONSTRAINT "commission_adjustment_source_type_check";
ALTER TABLE "finance_commission_adjustments" ADD CONSTRAINT "commission_adjustment_source_type_check" CHECK (source_type IN ('MANUAL', 'VERIFICATION_REVERSAL', 'NETTING_REVERSAL', 'LOCKED_FEE_SUPPLEMENT','FEE_CORRECTION','ECONOMIC_REALLOCATION'));
ALTER TABLE "order_fee_review_events" DROP CONSTRAINT "order_fee_review_events_action_check";
ALTER TABLE "order_fee_review_events" ADD CONSTRAINT "order_fee_review_events_action_check" CHECK (action IN ('SUBMIT','WITHDRAW','APPROVE','REJECT','REVOKE','SUPPLEMENT_APPROVE','CORRECTION_APPROVE'));
ALTER TABLE "finance_bills" ADD CONSTRAINT "finance_bills_purpose_check" CHECK (purpose IN ('NORMAL','CORRECTION_REVERSAL'));

-- 固化既有发票覆盖费用集合；迁移时更正尚未生效，按原账单行一次回填。
ALTER TABLE "finance_invoice_bills" ADD COLUMN "source_fee_ids" jsonb;
UPDATE "finance_invoice_bills" AS invoice_link SET "source_fee_ids" = COALESCE(
  (SELECT jsonb_agg(line.order_fee_id ORDER BY line.order_fee_id) FROM finance_bill_lines AS line WHERE line.bill_id = invoice_link.bill_id), '[]'::jsonb
);
ALTER TABLE "finance_invoice_bills" ALTER COLUMN "source_fee_ids" SET NOT NULL;
